import urllib.parse
import requests

def get_pages():
    with open('pages.txt') as f:
        return f.read().splitlines()

def refresh_page(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            print('Refreshed ' + url)
        else:
            print('Error refreshing ' + url)
    except Exception as e:
             print('Error refreshing ' + url + ': ' + str(e))

def main():
    pages = get_pages()

    for page in pages:
        parsed = urllib.parse.urlparse(page)
        if parsed.scheme in ['http', 'https']:
            refresh_page(page)

if __name__ == '__main__':
    main()

