import re
import requests
from bs4 import BeautifulSoup

def get_html(url):
    try:
        response = requests.get(url)
        return response.text
    except:
        return None

def extract_links(html):
    soup = BeautifulSoup(html, 'html.parser')
    links = soup.findAll('a')
    return [link.get('href') for link in links]

def is_valid_url(url):
    regex = re.compile(r'^(http|https)://')
    return regex.match(url)

def check_url(url):
    result = {}
    result['valid'] = is_valid_url(url)

    html = get_html(url)
    if html:
        result['status'] = 200
        result['redirect'] = None
        result['links'] = extract_links(html)
    else:
        result['status'] = 404
        result['redirect'] = None
        result['links'] = []

    return result

import os

def find_duplicate_files(path):
    duplicates = {}
    for root, dirs, files in os.walk(path):
        for f in files:
            filepath = os.path.join(root, f)
            file_size = os.path.getsize(filepath)

            if file_size in duplicates:
                duplicates[file_size].append(filepath)
            else:
                duplicates[file_size] = [filepath]

    for size, files in duplicates.items():
        if len(files) > 1:
            yield size, files

    return duplicates

if __name__ == '__main__':
    duplicates = find_duplicate_files('/home/user/')
    print(duplicates)

